#define ZONE_POSITION(row, col) ((row) << 4 | (col))

// potential naming scheme:
// zone1Position, zone2Position etc...
// zone1BoardPosition
// zone1BoardCoordinates
struct AI_Command
{
    u16 action; //actionID?
    u8 zone1Position; //board coordinate (lower 4 bits is column (zone), upper 4 bits is row)
    u8 zone2Position;
    u8 zone3Position;
    u8 zone4Position;
    u8 zone5Position;
    u8 zone6Position;
};

