// The "before" functions usually perform initial checks
// such as checking if there are any cards the action or effect acts upon in the first place

// The "after" functions check the aftermath of the effect, and decide whether it's worth activating
// for example, spell binding circle is not activated if the total atk and def of the player's monsters
// remains the same before and after

// Some effects only have a "before" function (e.g. heavy storm)
// (their "after" functions are empty)

