void AI_Main (void) {
  unsigned char i;
  TryActivatingTurnEffects();
  if (IsDuelOver() == TRUE)
    return;
  TryActivatingPermanentEffects();
  if (IsDuelOver() == TRUE)
    return;
  while (IsDuelOver() != TRUE) {
    u16 i;
    u16 temp;
    ClearAICommandData();
    sub_800F108();
    for (i = 0, gHideEffectText = 1; i < 0x3B2; i++) {
      InitAICommandData(i);
      if (sub_801A08C() == 1) {
        sub_800EE24(); // save duel data
        sub_800F1EC(); // initial prioritization of action
        sub_800E0F8(); // execute action to test the state of the duel (this is temporary and is reverted by the restore duel data function below)
        TryActivatingPermanentEffects(); // activate permanent effects
        sub_800F248(); // update priority one final time after the action has been performed and permanent effects have been activated
                       // and store it in the action priority array (unk504)
        sub_800EE94(); // restore duel data
      }
    }
    gHideEffectText = 0;
    temp = sub_800EF0C(); //get highest priority action
    if (temp == 0) // end AI's turn
      break;
    InitAICommandData(temp);
    TryAttackVoicing();
    sub_800E0D4(); // actually execute highest priority action
    if (gUnk2023EA0.unk18) {
      sub_801B66C();
      sub_8040EF0();
    }
    else
      UpdateDuelGfxExceptField();
    PlayActionSoundEffect();
    CheckWinConditionFINAL();
    CheckWinConditionExodia();
    TryActivatingPermanentEffects();
  }
  for (i = 0; i < 30; i++)
    WaitForVBlank();
}

