//Before spell activation funcs
//Priority struct member (unk2298) is set to current life points, attack, defense etc...
//depending on the effect
//For example, for life point healing effects, it sets it to current lifepoints
//Then the corresponding function that gets executed after the effect is (temporarily) activated
//sets the priority to the corresponding AI_PRIORITY value
//Effects that don't deal with life points etc. have their own unique AI_PRIORITY value
